acme_reload_hook_is_current(){
  # Dollar-prefixed names in the grep patterns are literal generated-hook text.
  # shellcheck disable=SC2016
  [[ -f $ACME_RELOAD && ! -L $ACME_RELOAD && -x $ACME_RELOAD ]] &&
    [[ $(grep -Fxc "$ACME_RELOAD_IDENTITY" "$ACME_RELOAD" 2>/dev/null || true) -eq 1 ]] &&
    awk '
      $0 == "if [[ ! -s $config ]]; then" {
        getline initial_if
        getline initial_commit
        getline initial_exit
        getline initial_end
        getline rollback
        getline normal_exit
        getline block_end
        valid = initial_if == "  if [[ ${SB_INITIAL_INSTALL:-0} == 1 ]]; then" &&
          initial_commit == "    commit_deployment" && initial_exit == "    exit 0" &&
          initial_end == "  fi" && rollback == "  rollback_deployment || true" &&
          normal_exit == "  exit 1" && block_end == "fi"
        exit
      }
      END { exit !valid }
    ' "$ACME_RELOAD" &&
    grep -Fqx 'source_cert="$source_dir/fullchain.pem"' "$ACME_RELOAD" 2>/dev/null &&
    grep -Fqx 'source_key="$source_dir/private.key"' "$ACME_RELOAD" 2>/dev/null &&
    grep -Fqx 'deployment_started=1' "$ACME_RELOAD" 2>/dev/null &&
    grep -Fqx '    restore_managed_links=1' "$ACME_RELOAD" 2>/dev/null &&
    grep -Fqx 'if ! mv -fT -- "$stage_cert" "$new_generation/fullchain.pem" ||' "$ACME_RELOAD" 2>/dev/null &&
    grep -Fqx '   ! mv -fT -- "$stage_key" "$new_generation/private.key" ||' "$ACME_RELOAD" 2>/dev/null &&
    grep -Fqx '     ! mv -Tf -- "$pointer_tmp" "$base/acme-live/current"; then' "$ACME_RELOAD" 2>/dev/null &&
    grep -Fqx "     ! install_managed_link \"\$cert\" 'acme-live/current/fullchain.pem'; then" "$ACME_RELOAD" 2>/dev/null &&
    grep -Fqx "     ! install_managed_link \"\$key\" 'acme-live/current/private.key'; then" "$ACME_RELOAD" 2>/dev/null &&
    grep -Fqx 'cert_public=$(openssl x509 -in "$stage_cert" -pubkey -noout 2>/dev/null) || exit 1' "$ACME_RELOAD" 2>/dev/null &&
    grep -Fqx 'key_public=$(openssl pkey -in "$stage_key" -pubout 2>/dev/null) || exit 1' "$ACME_RELOAD" 2>/dev/null &&
    grep -Fqx 'if restart_managed_service && sleep 1 && managed_service_active; then' "$ACME_RELOAD" 2>/dev/null &&
    bash -n "$ACME_RELOAD" >/dev/null 2>&1
}

prepare_acme_deploy_stage(){
  local path
  if [[ -e $ACME_STAGE || -L $ACME_STAGE ]]; then
    [[ -d $ACME_STAGE && ! -L $ACME_STAGE ]] || return 1
  else
    mkdir "$ACME_STAGE" || return 1
  fi
  chmod 700 "$ACME_STAGE" || return 1
  for path in "$ACME_STAGE_CERT" "$ACME_STAGE_KEY"; do
    [[ -e $path || -L $path ]] || continue
    [[ -f $path && ! -L $path ]] || return 1
  done
}

valid_acme_renewal_identity(){
  local identity
  [[ -x $ACME_BIN && -f $ACME_HOME/dnsapi/dns_cf.sh ]] || return 1
  identity=$(read_acme_identity 2>/dev/null) || return 1
  if ! load_certificate_metadata "$ACME_CERT" "$ACME_KEY" ||
     [[ $CERT_META_STATE != valid ]] ||
     ! certificate_identity_matches "$ACME_CERT" "$identity" ||
     ! load_acme_certificate_schedule "$identity"; then
    return 1
  fi
  printf '%s\n' "$identity"
}

recover_acme_renewal_identity(){
  local identity
  identity=$(detect_acme_identity 2>/dev/null) || return 1
  load_acme_certificate_schedule "$identity" || return 1
  write_acme_identity "$identity" || return 1
  printf '%s\n' "$identity"
}

register_acme_certificate_deployment(){
  local identity=$1 initial_install=${2:-0}
  [[ $initial_install == 0 || $initial_install == 1 ]] || return 1
  valid_hostname "$identity" || return 1
  acme_reload_hook_is_current || return 1
  prepare_acme_deploy_stage || return 1
  if ! SB_INITIAL_INSTALL="$initial_install" HOME="$SB_DIR" "$ACME_BIN" \
      --home "$ACME_HOME" --config-home "$ACME_HOME" \
      --install-cert -d "$identity" --ecc \
      --key-file "$ACME_STAGE_KEY" --fullchain-file "$ACME_STAGE_CERT" \
      --reloadcmd "$ACME_RELOAD"; then
    return 1
  fi
  managed_acme_live_layout_is_valid &&
    acme_deployment_config_is_current "$identity" &&
    load_certificate_metadata "$ACME_CERT" "$ACME_KEY" &&
    [[ $CERT_META_STATE == valid ]] &&
    certificate_identity_matches "$ACME_CERT" "$identity"
}

config_uses_acme_certificate(){
  [[ -s $SB_CONFIG ]] || return 1
  jq -e --arg cert "$ACME_CERT" --arg key "$ACME_KEY" '
    [.inbounds[] | select(.type == "hysteria2" and .tag == "hy2-sb" and
      .tls.certificate_path == $cert and .tls.key_path == $key)] | length == 1
  ' "$SB_CONFIG" >/dev/null 2>&1
}

config_uses_self_signed_certificate(){
  [[ -s $SB_CONFIG ]] || return 1
  jq -e --arg cert "$SB_DIR/cert.pem" --arg key "$SB_DIR/private.key" '
    [.inbounds[] | select(.type == "hysteria2" and .tag == "hy2-sb" and
      .tls.certificate_path == $cert and .tls.key_path == $key)] | length == 1
  ' "$SB_CONFIG" >/dev/null 2>&1
}

config_references_acme_state(){
  [[ -s $SB_CONFIG ]] || return 1
  jq -e --arg cert "$ACME_CERT" --arg key "$ACME_KEY" '
    [.inbounds[] | select(.type == "hysteria2" and .tag == "hy2-sb" and
      (.tls.certificate_path == $cert or .tls.key_path == $key))] | length > 0
  ' "$SB_CONFIG" >/dev/null 2>&1
}

validate_acme_state_backup(){
  local backup=$1 entry name mode owner expected_owner enforce_modes=1
  local -a state_names=(
    acme-cert.pem acme-private.key acme_server_name acme_reload.sh
    acme_renew.sh acme_renew.state cert_renew.sh .cert_mtime
  )
  [[ $backup == "$SB_DIR"/.acme-backup.* ]] || return 1
  name=${backup##*/}
  [[ $name =~ ^\.acme-backup\.[A-Za-z0-9]+$ ]] || return 1
  [[ -d $backup && ! -L $backup && -d $backup/files && ! -L $backup/files ]] || return 1
  expected_owner=$(id -u 2>/dev/null) || return 1
  case $(uname -s 2>/dev/null) in
    MINGW*|MSYS*) enforce_modes=0 ;;
  esac
  mode=$(stat -c '%a' "$backup" 2>/dev/null) || return 1
  owner=$(stat -c '%u' "$backup" 2>/dev/null) || return 1
  [[ $owner == "$expected_owner" ]] || return 1
  ((enforce_modes == 0)) || [[ $mode == 700 ]] || return 1
  mode=$(stat -c '%a' "$backup/files" 2>/dev/null) || return 1
  owner=$(stat -c '%u' "$backup/files" 2>/dev/null) || return 1
  [[ $owner == "$expected_owner" ]] || return 1
  ((enforce_modes == 0)) || [[ $mode == 700 ]] || return 1

  for entry in "$backup"/* "$backup"/.[!.]* "$backup"/..?*; do
    [[ -e $entry || -L $entry ]] || continue
    name=${entry##*/}
    case $name in
      files) [[ -d $entry && ! -L $entry ]] || return 1 ;;
      acme|live)
        [[ -d $entry && ! -L $entry ]] || return 1
        mode=$(stat -c '%a' "$entry" 2>/dev/null) || return 1
        owner=$(stat -c '%u' "$entry" 2>/dev/null) || return 1
        [[ $owner == "$expected_owner" ]] || return 1
        ((enforce_modes == 0)) || [[ $mode == 700 ]] || return 1
        ;;
      *) return 1 ;;
    esac
  done
  for entry in "$backup/files"/* "$backup/files"/.[!.]* "$backup/files"/..?*; do
    [[ -e $entry || -L $entry ]] || continue
    name=${entry##*/}
    printf '%s\n' "${state_names[@]}" | grep -Fxq -- "$name" || return 1
    owner=$(stat -c '%u' "$entry" 2>/dev/null) || return 1
    [[ $owner == "$expected_owner" ]] || return 1
    if [[ -L $entry ]]; then
      case $name in
        acme-cert.pem) [[ $(readlink "$entry" 2>/dev/null) == 'acme-live/current/fullchain.pem' ]] ;;
        acme-private.key) [[ $(readlink "$entry" 2>/dev/null) == 'acme-live/current/private.key' ]] ;;
        *) false ;;
      esac || return 1
    else
      [[ -f $entry ]] || return 1
      mode=$(stat -c '%a' "$entry" 2>/dev/null) || return 1
      ((enforce_modes == 0)) || (( (8#$mode & 0022) == 0 )) || return 1
    fi
  done
}

acme_state_backup_certificate_pair_is_valid(){
  local backup=$1 backup_cert backup_key current_target generation
  validate_acme_state_backup "$backup" || return 1
  backup_cert="$backup/files/acme-cert.pem"
  backup_key="$backup/files/acme-private.key"
  if [[ -f $backup_cert && ! -L $backup_cert && -f $backup_key && ! -L $backup_key ]]; then
    :
  elif [[ -L $backup_cert && -L $backup_key ]] &&
       [[ $(readlink "$backup_cert" 2>/dev/null) == 'acme-live/current/fullchain.pem' ]] &&
       [[ $(readlink "$backup_key" 2>/dev/null) == 'acme-live/current/private.key' ]] &&
       [[ -d $backup/live && ! -L $backup/live && -L $backup/live/current ]]; then
    current_target=$(readlink "$backup/live/current" 2>/dev/null) || return 1
    [[ $current_target =~ ^generations/gen\.[A-Za-z0-9]+$ ]] || return 1
    generation="$backup/live/$current_target"
    [[ -d $generation && ! -L $generation ]] || return 1
    backup_cert="$generation/fullchain.pem"
    backup_key="$generation/private.key"
    [[ -f $backup_cert && ! -L $backup_cert && -f $backup_key && ! -L $backup_key ]] || return 1
  else
    return 1
  fi
  certificate_time_valid "$backup_cert" && certificate_key_matches "$backup_cert" "$backup_key"
}

current_acme_state_is_safe_to_keep(){
  local identity
  identity=$(valid_acme_renewal_identity 2>/dev/null) || return 1
  managed_acme_live_layout_is_valid &&
    acme_deployment_config_is_current "$identity" &&
    cloudflare_acme_credentials_present &&
    acme_reload_hook_is_current
}

find_orphaned_acme_state_backup(){
  local path candidate='' count=0
  ACME_ORPHANED_BACKUP_COUNT=0
  [[ -z ${ACME_STATE_BACKUP:-} ]] || {
    return 2
  }
  for path in "$SB_DIR"/.acme-backup.*; do
    [[ -e $path || -L $path ]] || continue
    count=$((count + 1))
    candidate=$path
  done
  ACME_ORPHANED_BACKUP_COUNT=$count
  [[ $count -ne 0 ]] || return 1
  if [[ $count -ne 1 ]]; then
    return 2
  fi
  if ! validate_acme_state_backup "$candidate"; then
    return 2
  fi
  ACME_STATE_BACKUP=$candidate
}

acme_state_backup_candidates_exist(){
  local path
  for path in "$SB_DIR"/.acme-backup.*; do
    [[ -e $path || -L $path ]] && return 0
  done
  return 1
}

resolve_orphaned_acme_state_backup(){
  local scan_status menu confirmation backup
  if find_orphaned_acme_state_backup; then
    scan_status=0
  else
    scan_status=$?
  fi
  case $scan_status in
    1) return 0 ;;
    2)
      red "检测到 ${ACME_ORPHANED_BACKUP_COUNT:-0} 个异常或重复的 ACME 恢复点，拒绝自动选择"
      yellow "请人工检查 $SB_DIR/.acme-backup.*；处理前脚本不会执行证书、修复或卸载操作"
      return 1
      ;;
  esac
  backup=$ACME_STATE_BACKUP
  while true; do
    yellow "检测到上次证书操作留下的安全恢复点：$backup"
    green "1：恢复到证书操作前的状态"
    green "2：确认保留当前证书状态并删除恢复点"
    green "0：退出脚本，不做修改"
    readp "请选择【0-2】：" menu || return 1
    case $menu in
      1)
        if config_references_acme_state &&
           ! acme_state_backup_certificate_pair_is_valid "$backup"; then
          red "当前配置正在使用 ACME 证书，但恢复点中没有可用的证书与私钥，拒绝恢复"
          yellow "如已确认当前证书正常，可选择[2]删除恢复点"
          continue
        fi
        if ! restore_acme_state_backup 1; then
          red "恢复 ACME 状态失败，恢复点已保留；脚本将退出"
          return 1
        fi
        if config_uses_acme_certificate; then
          if ! cert_acme; then
            red "恢复后的 ACME 证书校验失败，恢复点已保留；脚本将退出"
            return 1
          fi
          if service_is_active && (! restartsb || ! service_is_active); then
            red "ACME 状态已恢复，但 sb 重启失败，恢复点已保留；脚本将退出"
            return 1
          fi
        fi
        if ! clear_acme_state_backup; then
          red "ACME 状态已恢复，但恢复点清理失败；脚本将退出"
          return 1
        fi
        green "证书操作前的 ACME 状态已恢复"
        return 0
        ;;
      2)
        if config_references_acme_state &&
           (! config_uses_acme_certificate ||
            ! current_acme_state_is_safe_to_keep); then
          red "当前 ACME 证书或续期状态未通过校验，拒绝删除唯一恢复点"
          continue
        fi
        red "删除恢复点后将无法自动回到证书操作前的状态"
        readp "请输入 DELETE 确认删除，其他输入取消：" confirmation || return 1
        [[ $confirmation == DELETE ]] || continue
        if ! clear_acme_state_backup; then
          red "删除 ACME 恢复点失败，脚本将退出"
          return 1
        fi
        green "已保留当前证书状态并删除旧恢复点"
        return 0
        ;;
      0|"") return 1 ;;
      *) red "请输入0、1或2" ;;
    esac
  done
}

begin_acme_state_backup(){
  local backup path
  local -a state_paths=(
    "$ACME_CERT" "$ACME_KEY" "$ACME_IDENTITY" "$ACME_RELOAD"
    "$SB_DIR/acme_renew.sh" "$SB_DIR/acme_renew.state"
    "$SB_DIR/cert_renew.sh" "$SB_DIR/.cert_mtime"
  )
  [[ -z ${ACME_STATE_BACKUP:-} ]] || return 1
  backup=$(mktemp -d "$SB_DIR/.acme-backup.XXXXXX") || return 1
  chmod 700 "$backup" || { rm -rf -- "$backup"; return 1; }
  if ! mkdir "$backup/files" || ! chmod 700 "$backup/files"; then
    rm -rf -- "$backup"
    return 1
  fi
  if [[ -e $ACME_HOME || -L $ACME_HOME ]]; then
    if [[ ! -d $ACME_HOME || -L $ACME_HOME ]] || ! cp -a -- "$ACME_HOME" "$backup/acme"; then
      rm -rf -- "$backup"
      return 1
    fi
  fi
  if [[ -e $ACME_LIVE || -L $ACME_LIVE ]]; then
    if [[ ! -d $ACME_LIVE || -L $ACME_LIVE ]] ||
       ! cp -a -- "$ACME_LIVE" "$backup/live"; then
      rm -rf -- "$backup"
      return 1
    fi
  fi
  for path in "${state_paths[@]}"; do
    [[ -e $path || -L $path ]] || continue
    if [[ -L $path ]]; then
      case $path in
        "$ACME_CERT") [[ $(readlink "$path" 2>/dev/null) == 'acme-live/current/fullchain.pem' ]] ;;
        "$ACME_KEY") [[ $(readlink "$path" 2>/dev/null) == 'acme-live/current/private.key' ]] ;;
        *) false ;;
      esac || { rm -rf -- "$backup"; return 1; }
      cp -Pp -- "$path" "$backup/files/${path##*/}" || {
        rm -rf -- "$backup"
        return 1
      }
    elif [[ ! -f $path ]] || ! cp -p -- "$path" "$backup/files/${path##*/}"; then
      rm -rf -- "$backup"
      return 1
    fi
  done
  ACME_STATE_BACKUP=$backup
  ACME_INFLIGHT_BACKUP=$backup
}

clear_acme_state_backup(){
  local backup=${ACME_STATE_BACKUP:-}
  [[ -n $backup ]] || return 0
  validate_acme_state_backup "$backup" || return 1
  rm -rf -- "$backup" || return 1
  ACME_STATE_BACKUP=
}

restore_acme_state_backup(){
  local backup=${ACME_STATE_BACKUP:-} retain_backup=${1:-0} stage entry name destination index
  local -a state_names=(
    acme-cert.pem acme-private.key acme_server_name acme_reload.sh
    acme_renew.sh acme_renew.state cert_renew.sh .cert_mtime
  )
  local -a state_paths=(
    "$ACME_CERT" "$ACME_KEY" "$ACME_IDENTITY" "$ACME_RELOAD"
    "$SB_DIR/acme_renew.sh" "$SB_DIR/acme_renew.state"
    "$SB_DIR/cert_renew.sh" "$SB_DIR/.cert_mtime"
  )
  [[ $retain_backup == 0 || $retain_backup == 1 ]] || return 1
  [[ -n $backup ]] || return 0
  validate_acme_state_backup "$backup" || return 1
  stage=$(mktemp -d "$SB_DIR/.acme-restore.XXXXXX") || return 1
  chmod 700 "$stage" || { rm -rf -- "$stage"; return 1; }
  if ! mkdir "$stage/files" || ! chmod 700 "$stage/files"; then
    rm -rf -- "$stage"
    return 1
  fi
  if [[ -e $backup/acme || -L $backup/acme ]]; then
    if [[ ! -d $backup/acme || -L $backup/acme ]] ||
       ! cp -a -- "$backup/acme" "$stage/acme"; then
      rm -rf -- "$stage"
      return 1
    fi
  fi
  if [[ -e $backup/live || -L $backup/live ]]; then
    if [[ ! -d $backup/live || -L $backup/live ]] ||
       ! cp -a -- "$backup/live" "$stage/live"; then
      rm -rf -- "$stage"
      return 1
    fi
  fi
  for entry in "$backup/files"/* "$backup/files"/.[!.]* "$backup/files"/..?*; do
    [[ -e $entry || -L $entry ]] || continue
    name=${entry##*/}
    printf '%s\n' "${state_names[@]}" | grep -Fxq -- "$name" || {
      rm -rf -- "$stage"
      return 1
    }
    if [[ -L $entry ]]; then
      case $name in
        acme-cert.pem) [[ $(readlink "$entry" 2>/dev/null) == 'acme-live/current/fullchain.pem' ]] ;;
        acme-private.key) [[ $(readlink "$entry" 2>/dev/null) == 'acme-live/current/private.key' ]] ;;
        *) false ;;
      esac || { rm -rf -- "$stage"; return 1; }
      cp -Pp -- "$entry" "$stage/files/$name" || { rm -rf -- "$stage"; return 1; }
    elif [[ -f $entry ]]; then
      cp -p -- "$entry" "$stage/files/$name" || { rm -rf -- "$stage"; return 1; }
    else
      rm -rf -- "$stage"
      return 1
    fi
  done

  rm -rf -- "$ACME_HOME" || { rm -rf -- "$stage"; return 1; }
  rm -rf -- "$ACME_LIVE" || { rm -rf -- "$stage"; return 1; }
  for destination in "${state_paths[@]}"; do
    rm -f -- "$destination" || { rm -rf -- "$stage"; return 1; }
  done
  if [[ -d $stage/acme ]]; then
    mv -fT -- "$stage/acme" "$ACME_HOME" || { rm -rf -- "$stage"; return 1; }
  fi
  if [[ -d $stage/live ]]; then
    mv -fT -- "$stage/live" "$ACME_LIVE" || { rm -rf -- "$stage"; return 1; }
  fi
  for index in "${!state_names[@]}"; do
    entry="$stage/files/${state_names[$index]}"
    [[ -e $entry || -L $entry ]] || continue
    destination=${state_paths[$index]}
    mv -fT -- "$entry" "$destination" || { rm -rf -- "$stage"; return 1; }
  done
  rm -rf -- "$stage" || return 1
  if [[ $retain_backup == 0 ]]; then
    rm -rf -- "$backup" || return 1
    ACME_STATE_BACKUP=
  fi
}

discard_acme_state(){
  local path failed=0
  rm -rf "$ACME_HOME" "$ACME_LIVE" || failed=1
  rm -f "$ACME_CERT" "$ACME_KEY" "$ACME_IDENTITY" "$ACME_RELOAD" \
    "$SB_DIR/acme_renew.sh" "$SB_DIR/acme_renew.state" \
    "$SB_DIR/cert_renew.sh" "$SB_DIR/.cert_mtime" || failed=1
  for path in "$ACME_HOME" "$ACME_LIVE" "$ACME_CERT" "$ACME_KEY" "$ACME_IDENTITY" "$ACME_RELOAD" \
    "$SB_DIR/acme_renew.sh" "$SB_DIR/acme_renew.state" \
    "$SB_DIR/cert_renew.sh" "$SB_DIR/.cert_mtime"; do
    [[ ! -e $path && ! -L $path ]] || failed=1
  done
  if ((failed)); then
    red "清理旧 ACME 状态不完整，已中止新证书申请"
    return 1
  fi
}

reset_acme_state(){
  local current force=${1:-0}
  if [[ $force != 1 ]] && config_references_acme_state; then
    red "当前服务正在使用 ACME 证书，请先切换为自签证书"
    return 1
  fi
  if [[ $force == 1 && -z ${ACME_STATE_BACKUP:-} ]]; then
    red "未找到 ACME 状态备份，拒绝强制清理正在使用的证书"
    return 1
  fi
  load_current_crontab || return 1
  current=$CURRENT_CRONTAB
  if crontab_has_acme_entries "$current"; then
    remove_acme_renew_cron || return 1
  fi
  discard_acme_state
}

issue_cloudflare_certificate(){
  local domain_input account_id cf_token backup_path
  local initial_install=${1:-0} retain_backup=${2:-0} reuse_backup=${3:-0}
  local -a issue_args
  [[ $initial_install == 0 || $initial_install == 1 ]] || return 1
  [[ $retain_backup == 0 || $retain_backup == 1 ]] || return 1
  [[ $reuse_backup == 0 || $reuse_backup == 1 ]] || return 1
  while true; do
    readp "请输入域名；泛域名请写成 *.example.com：" domain_input || return 1
    if normalize_acme_domain "$domain_input"; then
      break
    fi
    red "域名格式错误，请输入 example.com、sub.example.com 或 *.example.com"
  done
  while true; do
    readp "请输入 Cloudflare Account ID：" account_id || return 1
    account_id=${account_id,,}
    account_id=$(printf '%s' "$account_id" | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')
    if valid_cloudflare_account_id "$account_id"; then
      break
    fi
    red "Account ID 应为 32 位十六进制字符串"
  done
  yellow "DNS API 只负责证书验证；节点仍连接 VPS 公网 IP，域名仅作为 TLS SNI"
  yellow "API Token 需要 Zone / DNS / Edit 与 Zone / Zone / Read 权限"
  yellow "请把 Token 的 Zone 资源限制到目标域名"
  yellow "Token 将由 acme.sh 保存在仅 root 可读的 $ACME_HOME 配置中，用于自动续期"
  readp "请输入 Cloudflare API Token：" cf_token || return 1
  if [[ -z $cf_token ]]; then
    red "API Token 不能为空"
    return 1
  fi
  if [[ $reuse_backup == 1 ]]; then
    if [[ -z ${ACME_STATE_BACKUP:-} ]]; then
      red "原 ACME 状态备份不存在，已取消申请"
      return 1
    fi
  else
    if [[ -n ${ACME_STATE_BACKUP:-} ]] || ! begin_acme_state_backup; then
      red "无法安全备份现有 ACME 状态，已取消申请"
      return 1
    fi
  fi
  if [[ $reuse_backup == 1 ]]; then
    if ! reset_acme_state 1; then
      restore_acme_state_backup || red "恢复 ACME 状态失败，请立即检查 $SB_DIR"
      return 1
    fi
  else
    if ! reset_acme_state; then
      restore_acme_state_backup || red "恢复 ACME 状态失败，请立即检查 $SB_DIR"
      return 1
    fi
  fi
  if ! install_official_acme; then
    discard_acme_state
    restore_acme_state_backup || red "恢复旧 ACME 状态失败，请立即检查 $SB_DIR"
    return 1
  fi
  if ! write_acme_reload_hook; then
    discard_acme_state
    restore_acme_state_backup || red "恢复旧 ACME 状态失败，请立即检查 $SB_DIR"
    return 1
  fi
  issue_args=(--home "$ACME_HOME" --config-home "$ACME_HOME" --issue --server letsencrypt \
    --dns dns_cf --keylength ec-256 -d "$ACME_PRIMARY_DOMAIN")
  if [[ -n $ACME_WILDCARD_DOMAIN ]]; then
    issue_args+=(-d "$ACME_WILDCARD_DOMAIN")
    blue "将申请：$ACME_PRIMARY_DOMAIN + $ACME_WILDCARD_DOMAIN"
  else
    blue "将申请单域名证书：$ACME_PRIMARY_DOMAIN"
  fi
  if ! HOME="$SB_DIR" CF_Token="$cf_token" CF_Account_ID="$account_id" \
      CF_Zone_ID='' CF_Key='' CF_Email='' \
      "$ACME_BIN" "${issue_args[@]}"; then
    cf_token=
    discard_acme_state
    restore_acme_state_backup || red "恢复旧 ACME 状态失败，请立即检查 $SB_DIR"
    red "Cloudflare DNS 验证或证书签发失败"
    return 1
  fi
  cf_token=
  if ! write_acme_identity "$ACME_PRIMARY_DOMAIN"; then
    discard_acme_state
    restore_acme_state_backup || red "恢复旧 ACME 状态失败，请立即检查 $SB_DIR"
    return 1
  fi
  if ! register_acme_certificate_deployment "$ACME_PRIMARY_DOMAIN" "$initial_install"; then
    discard_acme_state
    restore_acme_state_backup || red "恢复旧 ACME 状态失败，请立即检查 $SB_DIR"
    red "证书签发成功，但安装到 $SB_DIR 失败"
    return 1
  fi
  if ! chmod 600 "$ACME_CERT" "$ACME_KEY"; then
    discard_acme_state
    restore_acme_state_backup || red "恢复旧 ACME 状态失败，请立即检查 $SB_DIR"
    return 1
  fi
  if ! cert_acme; then
    discard_acme_state
    restore_acme_state_backup || red "恢复旧 ACME 状态失败，请立即检查 $SB_DIR"
    red "证书有效性、域名或公私钥校验失败"
    return 1
  fi
  if [[ $retain_backup == 0 ]]; then
    if ! clear_acme_state_backup; then
      backup_path=$ACME_STATE_BACKUP
      ACME_STATE_BACKUP=
      yellow "新证书已签发，但临时备份未能删除：$backup_path"
    fi
  fi
  green "Cloudflare DNS API 证书申请完成"
}

self_signed_certificate_is_valid(){
  load_certificate_metadata "$SB_DIR/cert.pem" "$SB_DIR/private.key" &&
    [[ $CERT_META_STATE == valid ]] &&
    certificate_identity_matches "$SB_DIR/cert.pem" www.bing.com
}

generate_self_signed_certificate(){
  local selfsign_config key_tmp cert_tmp key_backup='' cert_backup='' path
  local key_path="$SB_DIR/private.key" cert_path="$SB_DIR/cert.pem"
  for path in "$key_path" "$cert_path"; do
    if [[ -e $path || -L $path ]]; then
      [[ -f $path && ! -L $path ]] || return 1
    fi
  done
  selfsign_config=$(mktemp "$SB_DIR/.selfsign-openssl.XXXXXX") || return 1
  key_tmp=$(mktemp "$SB_DIR/.selfsign-key.XXXXXX") || {
    rm -f "$selfsign_config"
    return 1
  }
  cert_tmp=$(mktemp "$SB_DIR/.selfsign-cert.XXXXXX") || {
    rm -f "$selfsign_config" "$key_tmp"
    return 1
  }
  if ! cat > "$selfsign_config" <<'SELFSIGN'
[req]
distinguished_name = subject
x509_extensions = extensions
prompt = no

[subject]
CN = www.bing.com

[extensions]
subjectAltName = DNS:www.bing.com
SELFSIGN
  then
    rm -f "$selfsign_config" "$key_tmp" "$cert_tmp"
    return 1
  fi
  if ! openssl ecparam -genkey -name prime256v1 -out "$key_tmp" ||
     ! openssl req -new -x509 -days 36500 -key "$key_tmp" \
       -out "$cert_tmp" -config "$selfsign_config" ||
     ! chmod 600 "$key_tmp" "$cert_tmp" ||
     ! load_certificate_metadata "$cert_tmp" "$key_tmp" ||
     [[ $CERT_META_STATE != valid ]] ||
     ! certificate_identity_matches "$cert_tmp" www.bing.com; then
    rm -f "$selfsign_config" "$key_tmp" "$cert_tmp"
    return 1
  fi
  rm -f "$selfsign_config"
  if [[ -f $key_path ]]; then
    key_backup=$(mktemp "$SB_DIR/.selfsign-key.backup.XXXXXX") || {
      rm -f "$key_tmp" "$cert_tmp"
      return 1
    }
    cp -p -- "$key_path" "$key_backup" || {
      rm -f "$key_tmp" "$cert_tmp" "$key_backup"
      return 1
    }
  fi
  if [[ -f $cert_path ]]; then
    cert_backup=$(mktemp "$SB_DIR/.selfsign-cert.backup.XXXXXX") || {
      rm -f "$key_tmp" "$cert_tmp" "$key_backup"
      return 1
    }
    cp -p -- "$cert_path" "$cert_backup" || {
      rm -f "$key_tmp" "$cert_tmp" "$key_backup" "$cert_backup"
      return 1
    }
  fi
  if ! mv -fT -- "$key_tmp" "$key_path" ||
     ! mv -fT -- "$cert_tmp" "$cert_path"; then
    if [[ -n $key_backup ]]; then cp -p -- "$key_backup" "$key_path"; else rm -f "$key_path"; fi
    if [[ -n $cert_backup ]]; then cp -p -- "$cert_backup" "$cert_path"; else rm -f "$cert_path"; fi
    rm -f "$key_tmp" "$cert_tmp" "$key_backup" "$cert_backup"
    return 1
  fi
  rm -f "$key_backup" "$cert_backup"
  chmod 600 "$key_path" "$cert_path" && self_signed_certificate_is_valid
}

inscertificate(){
  local menu acme_name
  red "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
  green "二、生成并设置相关证书"
  echo
  blue "自动生成bing自签证书中……" && sleep 2
  if ! generate_self_signed_certificate; then
    red "生成bing自签证书失败"
    return 1
  fi
  echo
  blue "生成bing自签证书成功"
  echo
  if acme_name=$(detect_acme_identity); then
    yellow "检测到可用的 ACME 域名证书：$acme_name"
    green "请选择 Hysteria2 证书模式"
    yellow "1：否！使用自签的证书 (回车默认)"
    yellow "2：使用已有的 $acme_name 域名证书"
    yellow "3：通过 Cloudflare Account ID + API Token 重新申请"
    yellow "   重新申请会删除本脚本现有的 ACME 证书与续期配置"
    while true; do
      readp "请选择【1-3】：" menu || return 1
      case "$menu" in
        ""|1) cert_self_signed; break ;;
        2)
          if cert_acme; then
            break
          fi
          ;;
        3)
          if issue_cloudflare_certificate 1; then break; fi
          yellow "继续使用自签证书"
          cert_self_signed
          break
          ;;
        *) red "请输入1、2或3" ;;
      esac
    done
  else
    green "请选择 Hysteria2 证书模式"
    yellow "1：使用自签证书 (回车默认)"
    yellow "2：使用官方 acme.sh + Cloudflare DNS API 申请域名证书"
    while true; do
      readp "请选择【1-2】：" menu || return 1
      case "$menu" in
        ""|1) cert_self_signed; break ;;
        2)
          if issue_cloudflare_certificate 1; then break; fi
          yellow "证书申请失败，继续使用自签证书"
          cert_self_signed
          break
          ;;
        *) red "请输入1或2" ;;
      esac
    done
  fi
}
# sb-module: 20-ports
valid_port(){
  local value=$1 minimum=${2:-1}
  [[ $value =~ ^[0-9]{1,5}$ ]] || return 1
  ((10#$value >= minimum && 10#$value <= 65535))
}

valid_uuid(){
  [[ $1 =~ ^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$ ]]
}

# Shadowsocks-2022 pre-shared key: exactly 44 base64 characters = 32 raw bytes
# with padding. sing-box 1.10.7 rejects every other shape at load time
# ("bad key" for a wrong length, "decode psk: illegal base64 data" for unpadded
# base64), and clients are stricter still, so only the canonical form is
# generated and accepted.
valid_ss_password(){
  [[ $1 =~ ^[A-Za-z0-9+/]{43}=$ ]]
}

generate_ss_password(){
  local key
  key=$(openssl rand -base64 32 2>/dev/null) || return 1
  key=${key//$'\n'/}
  valid_ss_password "$key" || return 1
  printf '%s\n' "$key"
}

valid_hostname(){
  local name=$1 label
  local -a labels
  [[ ${#name} -le 253 && $name == *.* && $name != .* && $name != *. ]] || return 1
  IFS='.' read -r -a labels <<< "$name"
  for label in "${labels[@]}"; do
    [[ ${#label} -ge 1 && ${#label} -le 63 ]] || return 1
    [[ $label =~ ^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?$ ]] || return 1
  done
}

port_conflict(){
  local port_number=$1 network=$2
  local -a ss_args
  case "$network" in
    tcp) ss_args=(-H -lnt) ;;
    udp) ss_args=(-H -lnu) ;;
    *) return 2 ;;
  esac
  ss "${ss_args[@]}" 2>/dev/null | awk '{print $(NF-1)}' |
    sed -n 's/.*:\([0-9][0-9]*\)$/\1/p' | grep -qx -- "$port_number"
}

chooseport(){
  local network=$1
  [[ $network == tcp || $network == udp ]] || return 1
  while true; do
    [[ -z $port ]] && port=$(shuf -i 10000-65535 -n 1)
    if ! valid_port "$port" 1; then
      red "端口必须是1-65535之间的整数"
    else
      port=$((10#$port))
    fi
    if valid_port "$port" 1 && port_conflict "$port" "$network"; then
      red "端口 $port/$network 已被占用"
    elif valid_port "$port" 1; then
      break
    fi
    readp "请重新输入端口 (1-65535，留空随机10000-65535): " port
  done
  blue "确认的端口：$port" && sleep 2
}

random_available_port(){
  local network=$1 candidate
  [[ $network == tcp || $network == udp ]] || return 1
  while true; do
    candidate=$(shuf -i 10000-65535 -n 1) || return 1
    if ! port_conflict "$candidate" "$network"; then
      printf '%s\n' "$candidate"
      return 0
    fi
  done
}

# Port selection for the optional Shadowsocks-2022 entry (menu [8]).
# Empty/1 = random, 2 = custom — the same shape the installer uses for its own
# port question. The result is returned in the global `port`.
choose_ss_port(){
  local choice
  while true; do
    yellow "1：自动生成随机端口 (10000-65535范围内)，回车默认"
    yellow "2：自定义端口"
    readp "请输入【1-2】：" choice || return 1
    case "$choice" in
      ""|1)
        port=$(random_available_port tcp) || return 1
        return 0
        ;;
      2)
        readp "\n设置Shadowsocks-2022端口 (可输入1-65535，留空随机10000-65535)：" port || return 1
        chooseport tcp
        return $?
        ;;
      *) red "请输入1或2" ;;
    esac
  done
}

hy2port(){
  readp "\n设置Hysteria2主端口 (可输入1-65535，留空随机10000-65535)：" port
  chooseport udp
  port_hy2=$port
}

insport(){
  red "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
  green "三、设置Hysteria2端口"
  yellow "1：自动生成随机端口 (10000-65535范围内)，回车默认。请确保VPS后台已开放所有端口"
  yellow "2：自定义端口。请确保VPS后台已开放指定的端口"
  while true; do
    readp "请输入【1-2】：" port
    case "$port" in
      ""|1)
        port_hy2=$(random_available_port udp) || return 1
        break
        ;;
      2)
        port=
        hy2port
        break
        ;;
      *) red "请输入1或2" ;;
    esac
  done
  echo
  blue "端口确认如下"
  blue "Hysteria-2端口：$port_hy2"
  red "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
  green "四、自动生成协议凭据"
  uuid=$("$SB_BIN" generate uuid)
  if ! valid_uuid "$uuid"; then
    red "生成UUID失败"
    return 1
  fi
  blue "Hysteria2 UUID（密码）：${uuid}"
  yellow "Shadowsocks-2022 入口默认不安装，需要时在菜单[8]可选功能里启用"
}
# sb-module: 30-server-config
# Generate server config JSON
render_server_config(){
  local output=$1 listen_addr relay_outbound_suffix route_final
  local ss_inbound_suffix ss_udp_rule
  [[ -n $output ]] || return 1
  relay_outbound_suffix=
  route_final=direct
  ss_inbound_suffix=
  ss_udp_rule=
  listen_addr=$(server_listen_address "$IPV6_SYSCTL_ROOT") || return 1
  [[ -n $listen_addr ]] || return 1
  # The Shadowsocks-2022 entry is optional and absent by default: a new install
  # creates only hysteria2, and repair enables it iff the source config has it.
  # Callers must set ss_entry_enabled=1 explicitly; "unset" means "do not emit".
  if [[ ${ss_entry_enabled:-0} -eq 1 ]]; then
    ss_inbound_suffix=$(printf ',\n    {\n      "type": "shadowsocks",\n      "sniff": true,\n      "sniff_override_destination": true,\n      "tag": "ss-sb",\n      "listen": "%s",\n      "listen_port": %s,\n      "network": "tcp",\n      "method": "%s",\n      "password": "%s"\n    }' \
      "$listen_addr" "$port_ss" "$SS_METHOD" "$ss_password") || return 1
    ss_udp_rule=$(printf '      {\n        "inbound": [\n          "ss-sb"\n        ],\n        "network": "udp",\n        "outbound": "block"\n      },\n')
    # Command substitution strips the trailing newline; put it back so the rule
    # keeps its own line (JSON tolerates the merge, readers do not).
    ss_udp_rule+=$'\n'
  fi
  # The optional upstream is re-read from relay.conf on every render, so a
  # rewritten config keeps the relay instead of silently falling back to a
  # direct exit. An unreadable state file is reported, not guessed at.
  if relay_settings_present; then
    if load_relay_settings; then
      route_final=relay
      relay_outbound_suffix=$(printf ',\n    {\n      "type": "shadowsocks",\n      "tag": "relay",\n      "server": "%s",\n      "server_port": %s,\n      "method": "%s",\n      "password": "%s"\n    }' \
        "$relay_server" "$relay_port" "$SS_METHOD" "$relay_password") || return 1
    else
      red "上游配置 $(relay_config_path) 无效，本次未启用上游（仍按直连出网）"
    fi
  elif [[ -s $SB_CONFIG ]] &&
       jq -e '[.outbounds[]? | select(.type == "shadowsocks")] | length > 0' "$SB_CONFIG" >/dev/null 2>&1; then
    # A hand-edited upstream outbound is not a state file we know about; say so
    # rather than letting the rewrite silently send traffic out directly again.
    yellow "当前配置里有一条上游出站，但 $(relay_config_path) 不存在，本次重写不会保留它"
    yellow "如需继续中转，请在菜单[8]上游/中转里重新设置一次"
  fi
  cat > "$output" <<EOF
{
  "log": {
    "disabled": false,
    "level": "info",
    "timestamp": true
  },
  "inbounds": [
    {
      "type": "hysteria2",
      "sniff": true,
      "sniff_override_destination": true,
      "tag": "hy2-sb",
      "listen": "${listen_addr}",
      "listen_port": ${port_hy2},
      "users": [
        {
          "password": "${uuid}"
        }
      ],
      "ignore_client_bandwidth": false,
      "tls": {
        "enabled": true,
        "alpn": [
          "h3"
        ],
        "certificate_path": "${certificatec_hy2}",
        "key_path": "${certificatep_hy2}"
      }
    }${ss_inbound_suffix}
  ],
  "outbounds": [
    {
      "type": "direct",
      "tag": "direct",
      "domain_strategy": "${ipv}"
    },
    {
      "type": "block",
      "tag": "block"
    }${relay_outbound_suffix}
  ],
  "route": {
    "final": "${route_final}",
    "rules": [
${ss_udp_rule}      {
        "protocol": [
          "quic",
          "stun"
        ],
        "outbound": "block"
      }
    ]
  }
}
EOF
}

inssbjson(){
  local candidate
  candidate=$(mktemp "$SB_DIR/.sb.json.install.XXXXXX") || return 1
  if ! render_server_config "$candidate"; then
    rm -f "$candidate"
    red "写入Sing-box候选配置失败"
    return 1
  fi
  chmod 600 "$candidate" || { rm -f "$candidate"; return 1; }
  if ! "$SB_BIN" check -c "$candidate" >/dev/null 2>&1; then
    red "初始配置未通过Sing-box v${CORE_VERSION}检查"
    "$SB_BIN" check -c "$candidate"
    rm -f "$candidate"
    return 1
  fi
  mv -fT -- "$candidate" "$SB_CONFIG"
}
# sb-module: 40-service
managed_path_is_trusted(){
  local path=$1 expected_owner owner mode
  [[ -e $path && ! -L $path ]] || return 1
  expected_owner=$(id -u 2>/dev/null) || return 1
  owner=$(stat -c '%u' "$path" 2>/dev/null) || return 1
  mode=$(stat -c '%a' "$path" 2>/dev/null) || return 1
  [[ $owner == "$expected_owner" && $mode =~ ^[0-7]{3,4}$ ]] || return 1
  (( (8#$mode & 0022) == 0 ))
}

managed_regular_file_is_trusted(){
  local path=$1
  [[ -f $path && ! -L $path ]] && managed_path_is_trusted "$path"
}

managed_symlink_is_trusted(){
  local path=$1 expected_owner owner
  [[ -L $path ]] || return 1
  expected_owner=$(id -u 2>/dev/null) || return 1
  owner=$(stat -c '%u' "$path" 2>/dev/null) || return 1
  [[ $owner == "$expected_owner" ]]
}

atomic_write_private_text(){
  local destination=$1 value=$2 candidate name
  name=${destination##*/}
  [[ ${destination%/*} == "$SB_DIR" && $name =~ ^[A-Za-z0-9._-]+$ ]] || return 1
  [[ -d $SB_DIR && ! -L $SB_DIR ]] && managed_path_is_trusted "$SB_DIR" || return 1
  candidate=$(mktemp "$SB_DIR/.managed-write.XXXXXX") || return 1
  if ! printf '%s\n' "$value" > "$candidate" || ! chmod 600 "$candidate" ||
     ! mv -fT -- "$candidate" "$destination"; then
    rm -f -- "$candidate"
    return 1
  fi
}

atomic_copy_private_file(){
  local source=$1 destination=$2 candidate name
  name=${destination##*/}
  [[ -f $source && ! -L $source && ${destination%/*} == "$SB_DIR" &&
     $name =~ ^[A-Za-z0-9._-]+$ ]] || return 1
  [[ -d $SB_DIR && ! -L $SB_DIR ]] && managed_path_is_trusted "$SB_DIR" || return 1
  candidate=$(mktemp "$SB_DIR/.managed-copy.XXXXXX") || return 1
  if ! cp -- "$source" "$candidate" || ! chmod 600 "$candidate" ||
     ! mv -fT -- "$candidate" "$destination"; then
    rm -f -- "$candidate"
    return 1
  fi
}

# --- Optional upstream ("线路机 -> 落地机") -------------------------------------
# relay.conf lives in the managed directory and is the single source of truth
# for the upstream: the config renderer re-reads it on every render, so no
# management flow (port change, credential change, repair) can drop the relay.
# Format is a three-line key=value file; there is deliberately no shell
# evaluation and no unknown-key tolerance.
relay_config_path(){
  printf '%s\n' "$SB_DIR/relay.conf"
}

relay_settings_present(){
  managed_regular_file_is_trusted "$(relay_config_path)"
}

relay_server_is_valid(){
  valid_ipv4 "$1" || valid_ipv6 "$1" || valid_hostname "$1"
}

load_relay_settings(){
  local config line key value count=0
  relay_server=
  relay_port=
  relay_password=
  config=$(relay_config_path) || return 1
  relay_settings_present || return 1
  while IFS= read -r line || [[ -n $line ]]; do
    [[ -n $line && $line == *=* ]] || return 1
    key=${line%%=*}
    value=${line#*=}
    case "$key" in
      server) relay_server=$value ;;
      port) relay_port=$value ;;
      password) relay_password=$value ;;
      *) return 1 ;;
    esac
    count=$((count + 1))
  done < "$config"
  [[ $count -eq 3 ]] || return 1
  relay_server_is_valid "$relay_server" || return 1
  valid_port "$relay_port" || return 1
  valid_ss_password "$relay_password" || return 1
}

save_relay_settings(){
  local server=$1 port=$2 password=$3 payload
  relay_server_is_valid "$server" || return 1
  valid_port "$port" || return 1
  valid_ss_password "$password" || return 1
  payload=$(printf 'server=%s\nport=%s\npassword=%s' "$server" "$port" "$password") || return 1
  atomic_write_private_text "$(relay_config_path)" "$payload"
}

clear_relay_settings(){
  local config
  config=$(relay_config_path) || return 1
  [[ ! -e $config && ! -L $config ]] && return 0
  managed_regular_file_is_trusted "$config" || return 1
  rm -f -- "$config"
}

write_managed_marker_at(){
  local directory=$1 marker_tmp marker="$1/.sb-managed"
  [[ ! -e $directory || -d $directory && ! -L $directory ]] || return 1
  mkdir -p "$directory" || return 1
  chmod 700 "$directory" || return 1
  marker_tmp=$(mktemp "$directory/.sb-managed.XXXXXX") || return 1
  if ! printf '%s\n' 'managed_by=sb.sh' 'identity=sb' 'directory=/etc/sb' > "$marker_tmp" ||
     ! chmod 600 "$marker_tmp" || ! mv -fT -- "$marker_tmp" "$marker"; then
    rm -f "$marker_tmp"
    return 1
  fi
}

write_managed_marker(){
  write_managed_marker_at "$SB_DIR"
}

managed_directory_is_owned(){
  [[ -d $SB_DIR && ! -L $SB_DIR && -f $SB_MANAGED_MARKER && ! -L $SB_MANAGED_MARKER ]] || return 1
  managed_path_is_trusted "$SB_DIR" && managed_regular_file_is_trusted "$SB_MANAGED_MARKER" || return 1
  grep -Fqx 'managed_by=sb.sh' "$SB_MANAGED_MARKER" 2>/dev/null &&
    grep -Fqx 'identity=sb' "$SB_MANAGED_MARKER" 2>/dev/null &&
    grep -Fqx 'directory=/etc/sb' "$SB_MANAGED_MARKER" 2>/dev/null
}

managed_directory_is_incomplete_creation(){
  local entry name
  [[ -d $SB_DIR && ! -L $SB_DIR ]] || return 1
  managed_directory_is_owned && return 1
  [[ ! -e $SB_MANAGED_MARKER && ! -L $SB_MANAGED_MARKER ]] || return 1
  # mv -fT is atomic, so an interrupt between mkdir and the marker rename can
  # only leave an empty directory or stray marker temporaries behind.
  for entry in "$SB_DIR"/* "$SB_DIR"/.[!.]* "$SB_DIR"/..?*; do
    [[ -e $entry || -L $entry ]] || continue
    name=${entry##*/}
    [[ $name == .sb-managed.* ]] || return 1
  done
}

prepare_managed_directory(){
  if [[ ! -e $SB_DIR && ! -L $SB_DIR ]]; then
    write_managed_marker
  elif managed_directory_is_owned; then
    chmod 700 "$SB_DIR"
  elif managed_directory_is_incomplete_creation; then
    yellow "检测到上次运行中断留下的空 $SB_DIR，按本脚本目录接管"
    write_managed_marker
  else
    red "检测到不属于本脚本的 $SB_DIR，拒绝覆盖"
    return 1
  fi
}

systemd_unit_is_owned(){
  local unit=$1 directory=$2 binary=$3 config=$4 marker_pattern=$5 service_name fragment
  [[ -f $unit && ! -L $unit ]] || return 1
  service_name=$(basename "$unit" .service)
  systemd_service_has_other_units "$service_name" "$unit" && return 1
  fragment=$(systemctl show "${service_name}.service" -p FragmentPath --value 2>/dev/null || true)
  [[ -z $fragment || $fragment == "$unit" ]] || return 1
  # Allow drop-ins (systemctl edit) — ownership of main unit still guarantees managed service
  grep -Eq "$marker_pattern" "$unit" 2>/dev/null &&
    grep -Fqx "WorkingDirectory=$directory" "$unit" 2>/dev/null &&
    grep -Fqx "ExecStart=$binary run -c $config" "$unit" 2>/dev/null
}

systemd_service_has_other_units(){
  local service=$1 expected=$2 base unit
  for base in /etc/systemd/system /run/systemd/system /usr/local/lib/systemd/system \
    /usr/lib/systemd/system /lib/systemd/system; do
    unit="$base/${service}.service"
    [[ $unit == "$expected" ]] && continue
    [[ -e $unit || -L $unit ]] && return 0
  done
  return 1
}

systemd_service_has_dropins(){
  local service=$1 base directory entry
  for base in /etc/systemd/system /run/systemd/system /usr/local/lib/systemd/system \
    /usr/lib/systemd/system /lib/systemd/system; do
    directory="$base/${service}.service.d"
    if [[ -L $directory || -e $directory && ! -d $directory ]]; then
      return 0
    fi
    if [[ -d $directory ]]; then
      for entry in "$directory"/* "$directory"/.[!.]* "$directory"/..?*; do
        [[ -e $entry || -L $entry ]] && return 0
      done
    fi
  done
  return 1
}

systemd_service_definition_present(){
  local service=$1 base unit
  systemd_service_has_dropins "$service" && return 0
  for base in /etc/systemd/system /run/systemd/system /usr/local/lib/systemd/system \
    /usr/lib/systemd/system /lib/systemd/system; do
    unit="$base/${service}.service"
    [[ -e $unit || -L $unit ]] && return 0
  done
  command -v systemctl >/dev/null 2>&1 && systemctl cat "$service" >/dev/null 2>&1
}

openrc_unit_is_owned(){
  local unit=$1 binary=$2 config=$3 marker_pattern=$4
  [[ -f $unit && ! -L $unit ]] || return 1
  grep -Eq "$marker_pattern" "$unit" 2>/dev/null &&
    grep -Fqx "command=\"$binary\"" "$unit" 2>/dev/null &&
    grep -Fqx "command_args=\"run -c $config\"" "$unit" 2>/dev/null
}

systemd_service_definition_is_repairable(){
  local unit=${1:-$SYSTEMD_UNIT}
  [[ -f $unit && ! -L $unit ]] || return 1
  grep -Fqx '# Managed by sb.sh' "$unit" 2>/dev/null || return 1
  systemd_service_has_other_units "$SB_SERVICE" "$unit" && return 1
  systemd_service_has_dropins "$SB_SERVICE" && return 1
  [[ ! -e $OPENRC_UNIT && ! -L $OPENRC_UNIT ]]
}

openrc_service_definition_is_repairable(){
  [[ -f $OPENRC_UNIT && ! -L $OPENRC_UNIT ]] || return 1
  grep -Fqx '# Managed by sb.sh' "$OPENRC_UNIT" 2>/dev/null || return 1
  ! systemd_service_definition_present "$SB_SERVICE"
}

service_definition_is_repairable(){
  if command -v apk >/dev/null 2>&1; then
    openrc_service_definition_is_repairable
  else
    systemd_service_definition_is_repairable "$SYSTEMD_UNIT"
  fi
}

write_service_definition(){
  local unit_tmp
  if command -v apk >/dev/null 2>&1; then
    unit_tmp=$(mktemp "/etc/init.d/.${SB_SERVICE}.XXXXXX") || return 1
    if ! cat > "$unit_tmp" <<EOF
#!/sbin/openrc-run
# Managed by sb.sh
description="sb sing-box service"
command="$SB_BIN"
command_args="run -c $SB_CONFIG"
command_background=true
pidfile="/var/run/${SB_SERVICE}.pid"
EOF
    then
      rm -f "$unit_tmp"
      return 1
    fi
    if ! chmod 700 "$unit_tmp" || ! mv -fT -- "$unit_tmp" "$OPENRC_UNIT"; then
      rm -f "$unit_tmp"
      return 1
    fi
  else
    unit_tmp=$(mktemp "/etc/systemd/system/.${SB_SERVICE}.service.XXXXXX") || return 1
    if ! cat > "$unit_tmp" <<EOF
[Unit]
# Managed by sb.sh
Description=sb sing-box service
After=network.target nss-lookup.target
[Service]
User=root
WorkingDirectory=$SB_DIR
CapabilityBoundingSet=CAP_NET_ADMIN CAP_NET_BIND_SERVICE CAP_NET_RAW
AmbientCapabilities=CAP_NET_ADMIN CAP_NET_BIND_SERVICE CAP_NET_RAW
ExecStart=$SB_BIN run -c $SB_CONFIG
ExecReload=/usr/bin/kill -HUP \$MAINPID
Restart=on-failure
RestartSec=10
LimitNOFILE=infinity
[Install]
WantedBy=multi-user.target
EOF
    then
      rm -f "$unit_tmp"
      return 1
    fi
    if ! chmod 600 "$unit_tmp" || ! mv -fT -- "$unit_tmp" "$SYSTEMD_UNIT"; then
      rm -f "$unit_tmp"
      return 1
    fi
  fi
}

sbservice(){
  if service_name_conflict; then
    red "检测到不属于sb.sh的同名 $SB_SERVICE 服务，拒绝覆盖"
    return 1
  fi
  if ! "$SB_BIN" check -c "$SB_CONFIG" >/dev/null 2>&1; then
    red "Sing-box配置检查失败，未创建服务"
    "$SB_BIN" check -c "$SB_CONFIG"
    return 1
  fi
  if ! write_service_definition; then
    red "写入 $SB_SERVICE 服务文件失败"
    return 1
  fi
  if command -v apk >/dev/null 2>&1; then
    if ! rc-update add "$SB_SERVICE" default >/dev/null 2>&1 || ! rc-service "$SB_SERVICE" start; then
      if cleanup_service; then
        red "创建或启动 $SB_SERVICE 服务失败，已清理服务文件"
      else
        red "创建或启动 $SB_SERVICE 服务失败，且自动清理未完成，请手动检查"
      fi
      return 1
    fi
  else
    if ! systemctl daemon-reload || ! systemctl enable --now "$SB_SERVICE"; then
      if cleanup_service; then
        red "创建或启动 $SB_SERVICE 服务失败，已清理服务文件"
      else
        red "创建或启动 $SB_SERVICE 服务失败，且自动清理未完成，请手动检查"
      fi
      return 1
    fi
  fi
  if ! service_is_active; then
    if cleanup_service; then
      red "$SB_SERVICE 服务启动后未保持运行，已清理服务文件"
    else
      red "$SB_SERVICE 服务启动后未保持运行，且自动清理未完成，请手动检查"
    fi
    return 1
  fi
  return 0
}

repair_managed_service(){
  if service_name_conflict && ! service_definition_is_repairable; then
    red "检测到不属于sb.sh的同名 $SB_SERVICE 服务，拒绝覆盖"
    return 1
  fi
  if ! installed_core_is_current || [[ ! -s $SB_CONFIG ]] ||
     ! "$SB_BIN" check -c "$SB_CONFIG" >/dev/null 2>&1; then
    red "内核或配置仍未通过检查，不能重建服务"
    return 1
  fi
  write_service_definition || return 1
  if command -v apk >/dev/null 2>&1; then
    rc-update add "$SB_SERVICE" default >/dev/null 2>&1 ||
      rc-update show default 2>/dev/null | grep -qE "(^|[[:space:]])${SB_SERVICE}([[:space:]]|$)" || return 1
    if service_is_active; then
      rc-service "$SB_SERVICE" restart >/dev/null 2>&1 || return 1
    else
      rc-service "$SB_SERVICE" start >/dev/null 2>&1 || return 1
    fi
  else
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    systemctl enable "$SB_SERVICE" >/dev/null 2>&1 || return 1
    systemctl restart "$SB_SERVICE" >/dev/null 2>&1 || return 1
  fi
  sleep 1
  service_is_active
}

restartsb(){
  if command -v apk >/dev/null 2>&1; then
    rc-service "$SB_SERVICE" restart
  else
    systemctl restart "$SB_SERVICE"
  fi
}

service_is_active(){
  if command -v apk >/dev/null 2>&1; then
    rc-service "$SB_SERVICE" status >/dev/null 2>&1
  else
    systemctl is-active --quiet "$SB_SERVICE"
  fi
}

service_is_owned(){
  if command -v apk >/dev/null 2>&1; then
    systemd_service_definition_present "$SB_SERVICE" && return 1
    openrc_unit_is_owned "$OPENRC_UNIT" "$SB_BIN" "$SB_CONFIG" '^# Managed by sb\.sh$'
  else
    [[ ! -e $OPENRC_UNIT && ! -L $OPENRC_UNIT ]] || return 1
    systemd_unit_is_owned "$SYSTEMD_UNIT" "$SB_DIR" "$SB_BIN" "$SB_CONFIG" '^# Managed by sb\.sh$'
  fi
}

formal_service_present(){
  [[ -e $OPENRC_UNIT || -L $OPENRC_UNIT ]] ||
    systemd_service_definition_present "$SB_SERVICE"
}

service_name_conflict(){
  formal_service_present || return 1
  service_is_owned && return 1
  service_definition_is_repairable && return 1
  return 0
}

service_exists(){
  service_is_owned
}

is_installed(){
  managed_directory_is_owned && service_exists && [[ -x $SB_BIN && -s $SB_CONFIG ]]
}

managed_install_data_present(){
  [[ -x $SB_BIN || -s $SB_CONFIG || -s $SB_DIR/private.key || -s $SB_DIR/cert.pem ||
     -s $ACME_KEY || -s $ACME_CERT || -s $SB_DIR/public.key ||
     -s ${SB_LAST_GOOD:-$SB_DIR/sb.json.last-good} ]]
}

installed_core_is_current(){
  local installed_core
  [[ -f $SB_BIN && ! -L $SB_BIN && -x $SB_BIN ]] || return 1
  managed_regular_file_is_trusted "$SB_BIN" || return 1
  installed_core=$("$SB_BIN" version 2>/dev/null | awk '/version/{print $NF}')
  [[ $installed_core == "$CORE_VERSION" ]]
}

managed_config_file_is_valid(){
  local source=$1
  [[ -s $source ]] && managed_regular_file_is_trusted "$source" || return 1
  installed_core_is_current || return 1
  "$SB_BIN" check -c "$source" >/dev/null 2>&1
}

save_last_good_config(){
  local source=${1:-$SB_CONFIG} destination=${SB_LAST_GOOD:-$SB_DIR/sb.json.last-good} candidate
  managed_config_file_is_valid "$source" || return 1
  if [[ -e $destination || -L $destination ]]; then
    [[ -f $destination && ! -L $destination ]] || return 1
    if cmp -s -- "$source" "$destination"; then
      chmod 600 "$destination"
      return
    fi
  fi
  candidate=$(mktemp "$SB_DIR/.sb.json.last-good.XXXXXX") || return 1
  if ! cp -p -- "$source" "$candidate" || ! chmod 600 "$candidate" ||
     ! mv -fT -- "$candidate" "$destination"; then
    rm -f "$candidate"
    return 1
  fi
}

installed_config_is_valid(){
  installed_core_is_current && [[ -s $SB_CONFIG ]] || return 1
  "$SB_BIN" check -c "$SB_CONFIG" >/dev/null 2>&1
}

cleanup_service(){
  local failed=0
  service_name_conflict && return 1
  if command -v apk >/dev/null 2>&1; then
    rc-service "$SB_SERVICE" stop >/dev/null 2>&1 || true
    service_is_active && return 1
    rc-update del "$SB_SERVICE" default >/dev/null 2>&1 || true
    rc-update show default 2>/dev/null | grep -qE "(^|[[:space:]])${SB_SERVICE}([[:space:]]|$)" && failed=1
    rm -f "$OPENRC_UNIT" || failed=1
    [[ ! -e $OPENRC_UNIT ]] || failed=1
  else
    systemctl stop "$SB_SERVICE" >/dev/null 2>&1 || true
    service_is_active && return 1
    systemctl disable "$SB_SERVICE" >/dev/null 2>&1 || true
    systemctl is-enabled "$SB_SERVICE" >/dev/null 2>&1 && failed=1
    rm -f "$SYSTEMD_UNIT" || failed=1
    [[ ! -e $SYSTEMD_UNIT ]] || failed=1
    systemctl daemon-reload >/dev/null 2>&1 || failed=1
  fi
  return "$failed"
}

sbactive(){
  if [[ ! -s $SB_CONFIG ]]; then
    red "配置文件 $SB_CONFIG 不存在，请重新安装"
    return 1
  fi
  if ! service_is_active; then
    red "Sing-box服务未运行，请检查日志"
    return 1
  fi
}

commit_config(){
  local candidate=$1 backup
  if [[ ! -s $candidate ]]; then
    red "候选配置不存在或为空"
    rm -f "$candidate"
    return 1
  fi
  if ! "$SB_BIN" check -c "$candidate" >/dev/null 2>&1; then
    red "新配置未通过 Sing-box v${CORE_VERSION} 检查，已取消修改"
    "$SB_BIN" check -c "$candidate"
    rm -f "$candidate"
    return 1
  fi
  backup=$(mktemp "$SB_DIR/.sb.json.backup.XXXXXX") || { rm -f "$candidate"; return 1; }
  if ! cp -p "$SB_CONFIG" "$backup"; then
    rm -f "$candidate" "$backup"
    return 1
  fi
  chmod 600 "$candidate"
  if ! mv -fT -- "$candidate" "$SB_CONFIG"; then
    rm -f "$candidate" "$backup"
    return 1
  fi
  if restartsb >/dev/null 2>&1 && sleep 1 && service_is_active; then
    rm -f "$backup"
    save_last_good_config "$SB_CONFIG" || yellow "配置已生效，但最后可用配置快照更新失败"
    return 0
  fi
  red "服务未能使用新配置启动，正在回滚"
  if cp -p "$backup" "$SB_CONFIG" && chmod 600 "$SB_CONFIG" && \
     restartsb >/dev/null 2>&1 && sleep 1 && service_is_active; then
    rm -f "$backup"
    red "已恢复修改前的配置和服务"
    return 1
  fi
  red "自动回滚失败！请立即检查服务；原配置备份保留在 $backup"
  return 2
}
# sb-module: 50-client-output
# IP detection for share links
save_server_ip(){
  local ip=$1 server_value client_value
  if valid_ipv4 "$ip"; then
    server_value=$ip
    client_value=$ip
  elif valid_ipv6 "$ip"; then
    server_value="[$ip]"
    client_value=$ip
  else
    return 1
  fi
  atomic_write_private_text "$SB_DIR/server_ip.log" "$server_value" &&
    atomic_write_private_text "$SB_DIR/server_ipcl.log" "$client_value"
}

ipuuid(){
  local menu
  v4v6_refresh || true
  if [[ -n $v4 && -n $v6 ]]; then
    green "调整IPv4/IPV6配置输出"
    yellow "1：刷新本地IP，使用IPV4配置输出 (回车默认) "
    yellow "2：刷新本地IP，使用IPV6配置输出"
    while true; do
      readp "请选择【1-2】：" menu
      case "$menu" in
        ""|1) save_server_ip "$v4"; break ;;
        2) save_server_ip "$v6"; break ;;
        *) red "请输入1或2" ;;
      esac
    done
  elif [[ -n $v4 ]]; then
    save_server_ip "$v4"
  elif [[ -n $v6 ]]; then
    save_server_ip "$v6"
  else
    red "未能检测到公网IPv4或IPv6地址"
    return 1
  fi
}

refresh_saved_ip(){
  local previous
  previous=
  if managed_regular_file_is_trusted "$SB_DIR/server_ipcl.log"; then
    previous=$(cat "$SB_DIR/server_ipcl.log" 2>/dev/null)
  fi
  v4v6_refresh || true
  if valid_ipv6 "$previous" && [[ -n $v6 ]]; then
    save_server_ip "$v6"
  elif valid_ipv4 "$previous" && [[ -n $v4 ]]; then
    save_server_ip "$v4"
  elif [[ -n $v4 ]]; then
    save_server_ip "$v4"
  elif [[ -n $v6 ]]; then
    save_server_ip "$v6"
  else
    [[ -s $SB_DIR/server_ip.log && -s $SB_DIR/server_ipcl.log ]] &&
      managed_regular_file_is_trusted "$SB_DIR/server_ip.log" &&
      managed_regular_file_is_trusted "$SB_DIR/server_ipcl.log"
  fi
}

# Read config from sb.json for share outputs
result(){
  if [[ ! -s $SB_CONFIG ]]; then
    red "配置文件不存在，请先安装"
    return 1
  fi
  if ! refresh_saved_ip; then
    red "没有可用的公网IP，拒绝生成无效节点"
    return 1
  fi
  server_ip=$(cat "$SB_DIR/server_ip.log" 2>/dev/null)
  server_ipcl=$(cat "$SB_DIR/server_ipcl.log" 2>/dev/null)
  if valid_ipv4 "$server_ipcl"; then
    [[ $server_ip == "$server_ipcl" ]] || return 1
  elif valid_ipv6 "$server_ipcl"; then
    [[ $server_ip == "[$server_ipcl]" ]] || return 1
  else
    red "保存的公网IP格式无效"
    return 1
  fi
  uuid=$(jq -er '.inbounds[] | select(.type == "hysteria2" and .tag == "hy2-sb") | .users[0].password' "$SB_CONFIG" 2>/dev/null) || return 1
  # The Shadowsocks-2022 entry is optional, so "no such inbound" is a normal
  # state rather than a broken config: everything downstream keys off ss_enabled.
  ss_enabled=0
  ss_port=
  ss_password=
  if ss_password=$(jq -er '.inbounds[] | select(.type == "shadowsocks" and .tag == "ss-sb") | .password' "$SB_CONFIG" 2>/dev/null); then
    ss_enabled=1
    ss_port=$(jq -er '.inbounds[] | select(.type == "shadowsocks" and .tag == "ss-sb") | .listen_port' "$SB_CONFIG" 2>/dev/null) || return 1
  else
    ss_password=
  fi
  hy2_port=$(jq -er '.inbounds[] | select(.type == "hysteria2" and .tag == "hy2-sb") | .listen_port' "$SB_CONFIG" 2>/dev/null) || return 1
  hy2_sniname=$(jq -er '.inbounds[] | select(.type == "hysteria2" and .tag == "hy2-sb") | .tls.key_path' "$SB_CONFIG" 2>/dev/null) || return 1
  if ! valid_uuid "$uuid" || ! valid_port "$hy2_port"; then
    red "服务端配置中的节点参数不完整或格式无效"
    return 1
  fi
  if [[ $ss_enabled -eq 1 ]] &&
     { ! valid_port "$ss_port" || ! valid_ss_password "$ss_password"; }; then
    red "服务端配置中的 Shadowsocks-2022 节点参数无效"
    return 1
  fi
  hy2_certificate_json=
  hy2_clash_ca=
  if [[ "$hy2_sniname" = "$SB_DIR/private.key" ]]; then
    if ! certificate_time_valid "$SB_DIR/cert.pem" ||
       ! certificate_key_matches "$SB_DIR/cert.pem" "$SB_DIR/private.key" ||
       ! certificate_identity_matches "$SB_DIR/cert.pem" www.bing.com; then
      red "自签证书校验失败，不能生成安全的Hysteria2客户端配置"
      return 1
    fi
    SHA256=$(openssl x509 -in "$SB_DIR/cert.pem" -noout -fingerprint -sha256 2>/dev/null | cut -d= -f2 | tr -d ':')
    [[ $SHA256 =~ ^[0-9A-Fa-f]{64}$ ]] || return 1
    hy2_certificate_json=$(jq -Rs . < "$SB_DIR/cert.pem") || return 1
    [[ -n $hy2_certificate_json ]] || return 1
    hy2_clash_ca="  ca-str: |"$'\n'"$(sed 's/^/    /' "$SB_DIR/cert.pem")"
    atomic_write_private_text "$SB_DIR/SHA256.txt" "$SHA256" || return 1
    hy2_name=www.bing.com
    sb_hy2_ip=$server_ip
    cl_hy2_ip=$server_ipcl
  else
    SHA256=""
    if ! ym=$(detect_acme_identity); then
      red "Acme证书身份无法确认，不能生成Hysteria2节点"
      return 1
    fi
    write_acme_identity "$ym" || return 1
    hy2_name=$ym
    sb_hy2_ip=$server_ip
    cl_hy2_ip=$server_ipcl
  fi
}


reshy2(){
  local output=${1:-$SB_DIR/hy2.txt}
  echo
  white "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
  hy2_link="hysteria2://$uuid@$sb_hy2_ip:$hy2_port?security=tls&alpn=h3&insecure=0&allowInsecure=0&sni=$hy2_name${SHA256:+&pinSHA256=$SHA256}#hy2-$hostname"
  printf '%s\n' "$hy2_link" > "$output" || return 1
  red "🚀【 Hysteria-2 】节点信息如下：" && sleep 2
  echo
  echo "分享链接【v2rayn、v2rayng、nekobox、小火箭shadowrocket】"
  echo -e "${yellow}$hy2_link${plain}"
  echo
  echo "二维码"
  qrencode -o - -t ANSIUTF8 "$hy2_link" || return 1
  white "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
  echo
}

resss(){
  local output=${1:-$SB_DIR/ss.txt}
  echo
  white "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
  # SIP002 puts base64("method:password") in the userinfo. The raw SS-2022 key
  # contains + / and =, which clients percent-decode inconsistently, so the
  # plain "ss://method:password@host" form must never be emitted.
  ss_link="ss://$(printf '%s:%s' "$SS_METHOD" "$ss_password" | base64 | tr -d '\r\n')@$server_ip:$ss_port#ss-$hostname"
  printf '%s\n' "$ss_link" > "$output" || return 1
  red "🚀【 Shadowsocks-2022 】节点信息如下：" && sleep 2
  echo
  echo "分享链接【sing-box、mihomo(Clash)、Shadowrocket、Nekobox】"
  echo -e "${yellow}$ss_link${plain}"
  echo
  echo "二维码"
  qrencode -o - -t ANSIUTF8 "$ss_link" || return 1
  white "~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~"
  echo
}

# Client config generation (kept compatible with sing-box 1.10.7)
sb_client(){
  local sbox_candidate clash_candidate hy2_certificate_field=
  local ss_outbound_field=
  local ss_selector_member=
  local ss_clash_proxy=
  local ss_clash_member=
  sbox_candidate=$(mktemp "$SB_DIR/.sbox.json.XXXXXX") || return 1
  clash_candidate=$(mktemp "$SB_DIR/.clash.yaml.XXXXXX") || { rm -f "$sbox_candidate"; return 1; }
  if [[ -n $hy2_certificate_json ]]; then
    hy2_certificate_field=$(printf ',\n        "certificate": %s' "$hy2_certificate_json")
  fi
  # Optional Shadowsocks-2022 entry: emit its client pieces only when the server
  # actually runs that inbound. Order stays SS-2022 first, Hysteria2 second.
  if [[ $ss_enabled -eq 1 ]]; then
    ss_outbound_field=$(printf '    {\n      "type": "shadowsocks",\n      "tag": "ss-%s",\n      "server": "%s",\n      "server_port": %s,\n      "method": "%s",\n      "password": "%s",\n      "network": "tcp"\n    },\n' \
      "$hostname" "$server_ipcl" "$ss_port" "$SS_METHOD" "$ss_password") || return 1
    ss_selector_member=$(printf '        "ss-%s",\n' "$hostname") || return 1
    ss_clash_proxy=$(printf -- '- name: ss-%s\n  type: ss\n  server: %s\n  port: %s\n  cipher: %s\n  password: %s\n  udp: false\n\n' \
